// Expand palette rows to truecolor pixel maps once at module load.
export const FRAMES: Record<AgentStatus, PixelFrame[]> = Object.fromEntries(
  Object.entries(FRAME_ROWS).map(([state, frames]) => [
    state,
    frames.map((rows) =>
      rows.map((row) => [...row].map((ch) => PALETTE[ch] ?? null)),
    ),
  ]),
) as Record<AgentStatus, PixelFrame[]>
